// biome-ignore-all lint/correctness/useExhaustiveDependencies: usePathStrokeMetrics intentionally accepts caller-controlled deps
import { type RefObject, useEffect, useState } from "react";

export function findPathLengthAtX(
  path: SVGPathElement | null,
  pathLength: number,
  targetX: number
): number {
  if (!path || pathLength === 0) {
    return 0;
  }
  let low = 0;
  let high = pathLength;
  const tolerance = 0.5;

  while (high - low > tolerance) {
    const mid = (low + high) / 2;
    const point = path.getPointAtLength(mid);
    if (point.x < targetX) {
      low = mid;
    } else {
      high = mid;
    }
  }
  return (low + high) / 2;
}

interface PathStrokeMetrics {
  pathD: string | null;
  pathLength: number;
}

const EMPTY_METRICS: PathStrokeMetrics = { pathD: null, pathLength: 0 };

/**
 * Caller passes the references that drive the rendered path (renderData,
 * innerWidth, etc.) as `deps`. A stringified summary like
 * `${renderData.length}:${innerWidth}` is *not* safe here — same-length
 * in-place mutations of `renderData` keep the summary identical, so the
 * effect would never re-fire and `pathD`/`pathLength` would stay frozen on
 * the previous geometry (the area fill repaints from `renderData` directly
 * and would diverge from the stroke).
 */
export function usePathStrokeMetrics(
  pathRef: RefObject<SVGPathElement | null>,
  deps: readonly unknown[],
  /**
   * Skip measuring while nothing reads the metrics (no dash tail / loading
   * pulse): `getTotalLength()` on a long path plus the follow-up render is
   * real work on every data update. Flipping to true re-measures.
   */
  enabled = true
): PathStrokeMetrics {
  const [metrics, setMetrics] = useState<PathStrokeMetrics>(EMPTY_METRICS);

  useEffect(() => {
    const path = pathRef.current;
    if (!(enabled && path)) {
      return;
    }
    const d = path.getAttribute("d");
    const len = d ? path.getTotalLength() : 0;
    setMetrics((prev) =>
      prev.pathD === d && prev.pathLength === len
        ? prev
        : { pathD: d, pathLength: len }
    );
  }, [enabled, ...deps]);

  return metrics;
}

export function resolveDashTailBounds(
  dashFromIndex: number | undefined,
  dataLength: number
): boolean {
  return (
    dashFromIndex != null &&
    dashFromIndex >= 0 &&
    dashFromIndex < dataLength - 1
  );
}

export function resolveDashStartX(
  data: Record<string, unknown>[],
  dashFromIndex: number,
  xScale: (value: Date | number) => number | undefined,
  xAccessor: (datum: Record<string, unknown>) => Date | number
): number {
  const dashFromPoint = data[dashFromIndex];
  if (!dashFromPoint) {
    return 0;
  }
  return xScale(xAccessor(dashFromPoint)) ?? 0;
}

import type { CurveFactory } from "d3-shape";
import { line as d3Line } from "d3-shape";

export interface SeriesPathPoint {
  x: number;
  y: number;
  key: string;
}

export function computeSeriesPathPoints(
  data: Record<string, unknown>[],
  xAccessor: (datum: Record<string, unknown>) => Date,
  xScale: (value: Date) => number | undefined,
  yScale: (value: number) => number | undefined,
  dataKey: string
): SeriesPathPoint[] {
  return data.map((datum, index) => {
    const xValue = xAccessor(datum);
    const yValue = datum[dataKey];
    return {
      x: xScale(xValue) ?? 0,
      y: typeof yValue === "number" ? (yScale(yValue) ?? 0) : 0,
      key: String(xValue.getTime?.() ?? index),
    };
  });
}

export function interpolateSeriesPathPoints(
  from: SeriesPathPoint[],
  to: SeriesPathPoint[],
  progress: number
): SeriesPathPoint[] {
  if (progress >= 1) {
    return to;
  }
  if (progress <= 0) {
    return from.length > 0 ? from : to;
  }

  const fromByKey = new Map(from.map((point) => [point.key, point]));

  return to.map((target, index) => {
    const source = fromByKey.get(target.key);
    if (source) {
      return {
        key: target.key,
        x: source.x + (target.x - source.x) * progress,
        y: source.y + (target.y - source.y) * progress,
      };
    }

    const previousTarget = index > 0 ? to[index - 1] : undefined;
    const previousSource = previousTarget
      ? fromByKey.get(previousTarget.key)
      : undefined;
    const nextTarget = index < to.length - 1 ? to[index + 1] : undefined;
    const nextSource = nextTarget ? fromByKey.get(nextTarget.key) : undefined;
    const anchor = previousSource ?? nextSource ?? from[0] ?? target;

    return {
      key: target.key,
      x: anchor.x + (target.x - anchor.x) * progress,
      y: anchor.y + (target.y - anchor.y) * progress,
    };
  });
}

export function seriesPathFromPoints(
  points: SeriesPathPoint[],
  curve: CurveFactory
): string {
  if (points.length === 0) {
    return "";
  }

  const generator = d3Line<SeriesPathPoint>()
    .x((point) => point.x)
    .y((point) => point.y)
    .curve(curve);

  return generator(points) ?? "";
}

const CURVE_SEGMENT_STEPS = 12;

/**
 * Records a d3 curve as a dense polyline (beziers subdivided) so the rendered
 * curve can be sampled as y(x).
 */
class PolylineRecorder {
  points: SeriesPathPoint[] = [];
  private x = 0;
  private y = 0;

  private push(x: number, y: number) {
    this.points.push({ x, y, key: "" });
    this.x = x;
    this.y = y;
  }

  moveTo(x: number, y: number) {
    this.push(x, y);
  }

  lineTo(x: number, y: number) {
    this.push(x, y);
  }

  bezierCurveTo(
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    x: number,
    y: number
  ) {
    const x0 = this.x;
    const y0 = this.y;
    for (let step = 1; step <= CURVE_SEGMENT_STEPS; step++) {
      const t = step / CURVE_SEGMENT_STEPS;
      const u = 1 - t;
      const a = u * u * u;
      const b = 3 * u * u * t;
      const c = 3 * u * t * t;
      const d = t * t * t;
      this.push(
        a * x0 + b * x1 + c * x2 + d * x,
        a * y0 + b * y1 + c * y2 + d * y
      );
    }
  }

  quadraticCurveTo(x1: number, y1: number, x: number, y: number) {
    const x0 = this.x;
    const y0 = this.y;
    for (let step = 1; step <= CURVE_SEGMENT_STEPS; step++) {
      const t = step / CURVE_SEGMENT_STEPS;
      const u = 1 - t;
      this.push(
        u * u * x0 + 2 * u * t * x1 + t * t * x,
        u * u * y0 + 2 * u * t * y1 + t * t * y
      );
    }
  }

  closePath() {
    // Open series paths only.
  }
}

/** Flattens the curve through `points` into a dense polyline sorted by x. */
export function flattenSeriesPath(
  points: SeriesPathPoint[],
  curve: CurveFactory
): SeriesPathPoint[] {
  if (points.length < 2) {
    return points;
  }
  const recorder = new PolylineRecorder();
  d3Line<SeriesPathPoint>()
    .x((point) => point.x)
    .y((point) => point.y)
    .curve(curve)
    // Minimal CanvasPath recorder — only implements the commands d3 curves emit.
    .context(recorder as unknown as CanvasRenderingContext2D)(points);
  return recorder.points.sort((a, b) => a.x - b.x);
}

/** y of a polyline (sorted by x) at `x`, clamped to its end points. */
export function samplePolylineY(polyline: SeriesPathPoint[], x: number) {
  const first = polyline[0];
  const last = polyline.at(-1);
  if (!(first && last)) {
    return 0;
  }
  if (x <= first.x) {
    return first.y;
  }
  if (x >= last.x) {
    return last.y;
  }
  let low = 0;
  let high = polyline.length - 1;
  while (high - low > 1) {
    const mid = Math.floor((low + high) / 2);
    if ((polyline[mid]?.x ?? 0) <= x) {
      low = mid;
    } else {
      high = mid;
    }
  }
  const a = polyline[low] ?? first;
  const b = polyline[high] ?? last;
  const span = b.x - a.x;
  return span > 0 ? a.y + ((b.y - a.y) * (x - a.x)) / span : a.y;
}

/**
 * Vertical morph between two polylines: both are sampled on a shared x grid
 * spanning the target's extent, and only y is interpolated, so the line rises
 * and falls into its new shape instead of points sliding sideways.
 */
export function morphSeriesPolylines(
  from: SeriesPathPoint[],
  to: SeriesPathPoint[],
  progress: number,
  sampleSpacingPx = 2
): SeriesPathPoint[] {
  const first = to[0];
  const last = to.at(-1);
  if (!(first && last) || from.length === 0) {
    return to;
  }
  const span = last.x - first.x;
  const count = Math.max(2, Math.ceil(span / sampleSpacingPx) + 1);
  const result: SeriesPathPoint[] = new Array(count);
  for (let index = 0; index < count; index++) {
    const x = first.x + (span * index) / (count - 1);
    const fromY = samplePolylineY(from, x);
    const toY = samplePolylineY(to, x);
    result[index] = { x, y: fromY + (toY - fromY) * progress, key: "" };
  }
  return result;
}

/** Data-only signature (x/y values), ignoring scale domain and width. */
export function seriesDataSignature(
  renderData: Record<string, unknown>[],
  xAccessor: (datum: Record<string, unknown>) => Date,
  dataKey: string
): string {
  return renderData
    .map((datum) => {
      const yValue = datum[dataKey];
      return `${xAccessor(datum).getTime()}:${typeof yValue === "number" ? yValue : ""}`;
    })
    .join(",");
}

export function seriesPathTransitionSignature({
  renderData,
  xAccessor,
  dataKey,
  innerWidth,
  xDomainMin,
  xDomainMax,
}: {
  renderData: Record<string, unknown>[];
  xAccessor: (datum: Record<string, unknown>) => Date;
  dataKey: string;
  innerWidth: number;
  xDomainMin: number;
  xDomainMax: number;
}): string {
  const values = renderData.map((datum) => {
    const xValue = xAccessor(datum);
    const yValue = datum[dataKey];
    return `${xValue.getTime()}:${typeof yValue === "number" ? yValue : ""}`;
  });

  return `${innerWidth}|${xDomainMin}|${xDomainMax}|${values.join(",")}`;
}

"use client";

import type { CurveFactory } from "d3-shape";
import { curveLinear } from "d3-shape";
import { animate, useReducedMotion } from "motion/react";
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { LINE_LOADING_PULSE_EASE } from "./line-loading-timing";
import {
  computeSeriesPathPoints,
  flattenSeriesPath,
  interpolateSeriesPathPoints,
  morphSeriesPolylines,
  type SeriesPathPoint,
  seriesDataSignature,
  seriesPathFromPoints,
  seriesPathTransitionSignature,
} from "./series-path-utils";

export interface UseAnimatedSeriesPathOptions {
  renderData: Record<string, unknown>[];
  xAccessor: (datum: Record<string, unknown>) => Date;
  xScale: (value: Date) => number | undefined;
  yScale: (value: number) => number | undefined;
  /**
   * Y-scale at the end of the y-domain tween. Data morphs animate toward this
   * scale so the line never chases a mid-tween domain out of the plot.
   * Default: `yScale`.
   */
  settledYScale?: (value: number) => number | undefined;
  dataKey: string;
  curve: CurveFactory;
  chartPhase: string;
  durationMs: number;
  innerWidth: number;
  enabled: boolean;
}

/**
 * Points currently on screen. `polyline` frames are dense samples of the
 * rendered curve (vertical morph) and are drawn with `curveLinear`.
 */
interface DisplayedSeriesPath {
  points: SeriesPathPoint[];
  polyline: boolean;
}

export function useAnimatedSeriesPath({
  renderData,
  xAccessor,
  xScale,
  yScale,
  settledYScale = yScale,
  dataKey,
  curve,
  chartPhase,
  durationMs,
  innerWidth,
  enabled,
}: UseAnimatedSeriesPathOptions) {
  const reducedMotion = useReducedMotion();
  const [animatedPath, setAnimatedPath] = useState<DisplayedSeriesPath | null>(
    null
  );
  const displayedRef = useRef<DisplayedSeriesPath | null>(null);
  const animatingRef = useRef(false);

  const xScaleDomain = useMemo(() => {
    const scaleWithDomain = xScale as { domain?: () => [Date, Date] };
    return scaleWithDomain.domain?.() ?? [new Date(0), new Date(0)];
  }, [xScale]);

  const transitionSignature = useMemo(
    () =>
      seriesPathTransitionSignature({
        renderData,
        xAccessor,
        dataKey,
        innerWidth,
        xDomainMin: xScaleDomain[0]?.getTime?.() ?? 0,
        xDomainMax: xScaleDomain[1]?.getTime?.() ?? 0,
      }),
    [renderData, xAccessor, dataKey, innerWidth, xScaleDomain]
  );

  const targetPoints = useMemo(
    () =>
      computeSeriesPathPoints(renderData, xAccessor, xScale, yScale, dataKey),
    [renderData, xAccessor, xScale, yScale, dataKey]
  );

  const dataSignature = useMemo(
    () => seriesDataSignature(renderData, xAccessor, dataKey),
    [renderData, xAccessor, dataKey]
  );

  const settledYDomainKey =
    (settledYScale as { domain?: () => number[] }).domain?.().join(",") ?? "";

  const prevTransitionSignatureRef = useRef(transitionSignature);
  const prevDataSignatureRef = useRef(dataSignature);
  const prevSettledYDomainKeyRef = useRef(settledYDomainKey);

  // Live scale/data inputs for the running tween. The y-domain tween rebuilds
  // `yScale` every frame, so these must not be effect deps — otherwise the
  // effect cleanup stops the path tween after its first frame.
  const latestRef = useRef({
    renderData,
    xAccessor,
    xScale,
    yScale,
    settledYScale,
    dataKey,
    curve,
  });
  // Synced in a layout effect declared before the tween effect (not during
  // render) so `renderFrame(0)` and every animation frame see this commit's
  // inputs.
  useLayoutEffect(() => {
    latestRef.current = {
      renderData,
      xAccessor,
      xScale,
      yScale,
      settledYScale,
      dataKey,
      curve,
    };
  });
  const computeLatestTarget = (settled = false) => {
    const latest = latestRef.current;
    return computeSeriesPathPoints(
      latest.renderData,
      latest.xAccessor,
      latest.xScale,
      settled ? latest.settledYScale : latest.yScale,
      latest.dataKey
    );
  };

  const shouldAnimate =
    enabled &&
    !reducedMotion &&
    chartPhase === "ready" &&
    durationMs > 0 &&
    renderData.length > 0;

  // Drop a stale tween frame as soon as animation is no longer allowed —
  // adjusted during render rather than via setState in the effect below.
  if (!shouldAnimate && animatedPath !== null) {
    setAnimatedPath(null);
  }

  // Layout effect so frame 0 (the previous shape) is committed before paint;
  // otherwise the new target flashes for a frame before the tween starts.
  // biome-ignore lint/correctness/useExhaustiveDependencies: scales/targets are read live via latestRef; only a new data signature should restart the tween
  useLayoutEffect(() => {
    const dataChanged = prevDataSignatureRef.current !== dataSignature;
    prevDataSignatureRef.current = dataSignature;
    const yDomainChanged =
      prevSettledYDomainKeyRef.current !== settledYDomainKey;
    prevSettledYDomainKeyRef.current = settledYDomainKey;

    if (!shouldAnimate) {
      animatingRef.current = false;
      displayedRef.current = { points: targetPoints, polyline: false };
      prevTransitionSignatureRef.current = transitionSignature;
      return;
    }

    if (prevTransitionSignatureRef.current === transitionSignature) {
      return;
    }
    prevTransitionSignatureRef.current = transitionSignature;

    const from = displayedRef.current ?? {
      points: targetPoints,
      polyline: false,
    };
    if (from.points.length === 0) {
      displayedRef.current = { points: targetPoints, polyline: false };
      return;
    }

    animatingRef.current = true;
    // New/removed data points: morph vertically on a shared x grid so the line
    // rises and falls into shape. Same data with a moved x-domain (brush pan /
    // resize): slide points by key so the series tracks the viewport.
    const morph = dataChanged || from.polyline;
    const fromPolyline = from.polyline
      ? from.points
      : flattenSeriesPath(from.points, curve);
    // When new data also moves the y-domain, hold the line in place while the
    // grid and y-axis tween to the new scale, then morph straight to its
    // settled pixels — morphing against the mid-tween scale sends the line
    // far outside the plot when the magnitude changes (e.g. ~15k → ~10).
    const holdForYDomain = morph && dataChanged && yDomainChanged;

    const renderFrame = (progress: number) => {
      // Morphs target the settled scale; x-domain slides (brush) track the
      // live y-domain tween so the series stays glued to the grid.
      const currentTarget = computeLatestTarget(morph);
      const next: DisplayedSeriesPath = morph
        ? {
            points: morphSeriesPolylines(
              fromPolyline,
              flattenSeriesPath(currentTarget, latestRef.current.curve),
              progress
            ),
            polyline: true,
          }
        : {
            points: interpolateSeriesPathPoints(
              from.points,
              currentTarget,
              progress
            ),
            polyline: false,
          };
      displayedRef.current = next;
      setAnimatedPath(next);
    };
    renderFrame(0);

    const control = animate(0, 1, {
      delay: holdForYDomain ? durationMs / 1000 : 0,
      duration: durationMs / 1000,
      ease: [...LINE_LOADING_PULSE_EASE],
      onUpdate: renderFrame,
      onComplete: () => {
        animatingRef.current = false;
        displayedRef.current = {
          points: computeLatestTarget(),
          polyline: false,
        };
        setAnimatedPath(null);
      },
    });

    return () => {
      control.stop();
      animatingRef.current = false;
    };
  }, [
    transitionSignature,
    dataSignature,
    shouldAnimate,
    chartPhase,
    durationMs,
    enabled,
    reducedMotion,
    renderData.length,
  ]);

  // Must run after the tween effect: on a data change the tween needs the
  // previously displayed points as its `from`, not the new target.
  useEffect(() => {
    if (!animatingRef.current) {
      displayedRef.current = { points: targetPoints, polyline: false };
    }
  }, [targetPoints]);

  const pathD = useMemo(
    () =>
      animatedPath
        ? seriesPathFromPoints(
            animatedPath.points,
            animatedPath.polyline ? curveLinear : curve
          )
        : seriesPathFromPoints(targetPoints, curve),
    [animatedPath, targetPoints, curve]
  );

  return {
    pathD,
    isPathAnimating: animatedPath != null,
  };
}

import type { TooltipData } from "./chart-context";
import type { ChartSelection } from "./use-chart-interaction";

// Pure geometry for the hover-highlight band, split out from the hook so it can
// be unit-tested without React/motion (see __tests__).
//
// The band is the pixel x-range one data point either side of the hovered point:
//   [ xScale(t(idx-1)), xScale(t(idx+1)) ]
// `<HighlightSegment>` then re-strokes the base path clipped to that band, so the
// highlight always traces the line itself. Selecting the band by data index
// assumes x is monotone along the path, which holds for a time series. On a curve
// that overshoots in x (curveNatural, curveBasis) a band edge can land a few
// pixels short, slightly narrowing the bright slice but never detaching it.

export interface SegmentBounds {
  /** Left edge of the highlight band, in pixels. */
  x: number;
  /** Width of the highlight band, in pixels. */
  width: number;
  isActive: boolean;
}

export const INACTIVE_SEGMENT: SegmentBounds = {
  x: 0,
  width: 0,
  isActive: false,
};

/**
 * The highlight band `{x, width}` in pixel space, from the data + `xScale` plus
 * the current hover/selection. Hover spans one data point either side of the dot
 * (clamped to the ends); an active drag-selection uses the dragged pixel range
 * directly and takes priority over hover. `span` widens the hover band to that
 * many data points either side (default 1).
 */
export function computeSegmentBounds(
  data: Record<string, unknown>[],
  xScale: (value: Date) => number | undefined,
  xAccessor: (d: Record<string, unknown>) => Date,
  tooltipData: Pick<TooltipData, "index"> | null | undefined,
  selection:
    | Pick<ChartSelection, "active" | "startX" | "endX">
    | null
    | undefined,
  span = 1
): SegmentBounds {
  if (data.length === 0) {
    return INACTIVE_SEGMENT;
  }

  if (selection?.active) {
    const x = Math.min(selection.startX, selection.endX);
    const width = Math.abs(selection.endX - selection.startX);
    return { x, width, isActive: true };
  }

  if (!tooltipData) {
    return INACTIVE_SEGMENT;
  }

  const idx = tooltipData.index;
  const reach = Math.max(1, Math.round(span));
  const startIdx = Math.max(0, idx - reach);
  const endIdx = Math.min(data.length - 1, idx + reach);
  const startPoint = data[startIdx];
  const endPoint = data[endIdx];
  if (!(startPoint && endPoint)) {
    return INACTIVE_SEGMENT;
  }

  const startX = xScale(xAccessor(startPoint)) ?? 0;
  const endX = xScale(xAccessor(endPoint)) ?? 0;
  return { x: startX, width: Math.max(0, endX - startX), isActive: true };
}

"use client";

import { type MotionValue, motion } from "motion/react";
import { type RefObject, useId, useLayoutEffect, useRef } from "react";

// Hover-highlight overlay: re-strokes the base path `d`, clipped to a vertical
// band whose x/width spring to track the hovered point, so only the segment
// around the dot shows brighter. The band comes from `useHighlightSegment`;
// because the bright stroke reuses the base `d`, it follows whatever curve is
// drawn (see `highlight-segment-bounds.ts` for the band-extent caveat).

/** Soft glow behind the highlight segment: a blurred copy of its stroke. */
export interface HighlightSegmentGlow {
  /** `url(#…)` reference to an `feGaussianBlur` filter. */
  filter: string;
  opacity: number;
  strokeWidth: number;
}

export interface HighlightSegmentProps {
  /** Ref to the rendered base stroke `<path>` — its `d` is re-used verbatim. */
  pathRef: RefObject<SVGPathElement | null>;
  /** Whether to render (caller gates on showHighlight + active + loaded). */
  visible: boolean;
  stroke: string;
  strokeWidth: number;
  /** Plot height — the clip band spans it fully. */
  height: number;
  /** Spring-eased left edge of the clip band (px). */
  x: MotionValue<number>;
  /** Spring-eased width of the clip band (px). */
  width: MotionValue<number>;
  /**
   * Soft ends: fade the segment in / out over this percentage (0–50) of the
   * band width at each side, via a mask. `0` = hard-edged clip. Default: 0
   */
  fadeLength?: number;
  /** Optional glow drawn behind the segment, inside the same band. */
  glow?: HighlightSegmentGlow;
}

export function HighlightSegment({
  pathRef,
  visible,
  stroke,
  strokeWidth,
  height,
  x,
  width,
  fadeLength = 0,
  glow,
}: HighlightSegmentProps) {
  const bandId = useId();
  const fadeId = `${bandId}-fade`;
  const highlightRef = useRef<SVGPathElement>(null);
  const glowRef = useRef<SVGPathElement>(null);

  // Copy the base stroke's `d` after commit (before paint) instead of reading
  // `pathRef.current` during render — same frame, and it picks up the base
  // path's `d` from this commit rather than the previous one.
  useLayoutEffect(() => {
    if (!visible) {
      return;
    }
    const d = pathRef.current?.getAttribute("d") || "";
    highlightRef.current?.setAttribute("d", d);
    glowRef.current?.setAttribute("d", d);
  });

  if (!visible) {
    return null;
  }

  const fade = Math.min(50, Math.max(0, fadeLength));
  const soft = fade > 0;
  // Bleed by the widest stroke so a stroke at the min/max value keeps its
  // full width (and the glow isn't cropped vertically).
  const bleed = Math.max(strokeWidth, glow ? glow.strokeWidth * 2 : 0);
  const band = (
    <motion.rect
      fill={soft ? `url(#${fadeId})` : undefined}
      height={height + bleed * 2}
      width={width}
      x={x}
      y={-bleed}
    />
  );

  return (
    <>
      <defs>
        {soft ? (
          // Horizontal luminance ramp over the band (objectBoundingBox is fine:
          // the band rect always has area). White = visible.
          <>
            <linearGradient id={fadeId} x1="0" x2="1" y1="0" y2="0">
              <stop offset="0" stopColor="white" stopOpacity={0} />
              <stop offset={fade / 100} stopColor="white" stopOpacity={1} />
              <stop offset={1 - fade / 100} stopColor="white" stopOpacity={1} />
              <stop offset="1" stopColor="white" stopOpacity={0} />
            </linearGradient>
            {/* userSpaceOnUse region: a near-flat path has a thin bbox, so the
                default objectBoundingBox region would crop the stroke. */}
            <mask
              height="300%"
              id={bandId}
              maskUnits="userSpaceOnUse"
              width="300%"
              x="-100%"
              y="-100%"
            >
              {band}
            </mask>
          </>
        ) : (
          <clipPath id={bandId}>{band}</clipPath>
        )}
      </defs>
      <motion.g
        animate={{ opacity: 1 }}
        clipPath={soft ? undefined : `url(#${bandId})`}
        exit={{ opacity: 0 }}
        initial={{ opacity: 0 }}
        mask={soft ? `url(#${bandId})` : undefined}
        transition={{ duration: 0.4, ease: "easeInOut" }}
      >
        {glow ? (
          <path
            fill="none"
            filter={glow.filter}
            ref={glowRef}
            stroke={stroke}
            strokeLinecap="round"
            strokeOpacity={glow.opacity}
            strokeWidth={glow.strokeWidth}
          />
        ) : null}
        <path
          fill="none"
          ref={highlightRef}
          stroke={stroke}
          strokeLinecap="round"
          strokeWidth={strokeWidth}
        />
      </motion.g>
    </>
  );
}

